import React, { useState, useEffect } from 'react';
import { getNearbyUsers, updateDiscoverySettings, likeUser } from '../services/api';
import { Modal, Button, Badge } from 'react-bootstrap';

const fixImageUrl = (url) => {
    if (!url) return 'https://via.placeholder.com/150';
    if (url.includes('/static/uploads/')) {
        const path = url.substring(url.indexOf('/static/uploads/'));
        const backendHost = window.location.hostname === 'localhost' ? 'localhost' : window.location.hostname;
        return `http://${backendHost}:5000${path}`;
    }
    return url;
};

const DiscoverFeed = ({ currentUser, setActiveTab, myMatches = [], startChat, viewProfile, handleExpressInterest }) => {
    const [users, setUsers] = useState([]);
    const [radius, setRadius] = useState(50);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState(null);
    const [showModal, setShowModal] = useState(false);
    const [selectedUser, setSelectedUser] = useState(null);

    // Mock phone if no currentUser is passed in for testing
    const myPhone = currentUser?.phone || '0721143189';

    const fetchUsers = async (currentRadius) => {
        setLoading(true);
        setError(null);
        try {
            const response = await getNearbyUsers(myPhone, currentRadius);
            let usersArray = [];

            if (Array.isArray(response)) {
                usersArray = response;
            } else if (response && Array.isArray(response.data)) {
                usersArray = response.data;
            } else if (response && Array.isArray(response.users)) {
                usersArray = response.users;
            }

            setUsers(usersArray);
        } catch (err) {
            setError("Failed to fetch nearby users.");
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        fetchUsers(radius);
    // eslint-disable-next-line react-hooks/exhaustive-deps
    }, []);

    const handleRadiusChange = (e) => {
        setRadius(parseInt(e.target.value));
    };

    const handleRadiusSubmit = async () => {
        try {
            await updateDiscoverySettings(myPhone, radius);
            fetchUsers(radius);
        } catch (err) {
            setError("Failed to update distance settings.");
        }
    };

    const handleLike = async (targetPhone) => {
        try {
            await likeUser(myPhone, targetPhone);
            // Remove user from UI
            setUsers(users.filter(u => u.phone_number !== targetPhone));
        } catch (err) {
            console.error(err);
        }
    };

    const handlePass = async (targetPhone) => {
        try {
            await fetch(`${process.env.REACT_APP_API_URL || `http://${window.location.hostname}:5000`}/api/user/match/pass`, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ phone: myPhone, target_phone: targetPhone })
            });
            setUsers(users.filter(u => u.phone_number !== targetPhone));
        } catch (err) {
            console.error(err);
        }
    };

    const handleFindNearby = () => {
        if ("geolocation" in navigator) {
            navigator.geolocation.getCurrentPosition(async (position) => {
                const { latitude, longitude } = position.coords;
                try {
                    await fetch(`${process.env.REACT_APP_API_URL || `http://${window.location.hostname}:5000`}/api/user/${myPhone}/location`, {
                        method: 'POST',
                        headers: { 'Content-Type': 'application/json' },
                        body: JSON.stringify({ latitude, longitude })
                    });
                    alert("Location updated! Fetching users nearby...");
                    fetchUsers(radius);
                } catch (err) {
                    alert("Failed to update location on server.");
                }
            }, (error) => {
                alert("Please enable GPS/Location services to use this feature.");
            });
        } else {
            alert("Geolocation is not supported by your browser.");
        }
    };

    const handleViewProfile = (user) => {
        setSelectedUser(user);
        setShowModal(true);
    };

    const handleCloseModal = () => {
        setShowModal(false);
        setSelectedUser(null);
    };

    return (
        <div style={{ padding: '30px', maxWidth: '1200px', margin: '0 auto' }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '30px' }}>
                <h1 style={{ fontSize: '2rem', color: '#1f2937', margin: 0 }}>Discover Nearby</h1>
                <div style={{ display: 'flex', gap: '10px' }}>
                    <button 
                        onClick={handleFindNearby}
                        style={{ padding: '10px 20px', backgroundColor: '#3b82f6', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer', fontWeight: 'bold' }}
                    >
                        📍 Find Nearby
                    </button>
                    <button 
                        onClick={() => setActiveTab && setActiveTab('passport')}
                        style={{ padding: '10px 20px', backgroundColor: '#8b5cf6', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer', fontWeight: 'bold' }}
                    >
                        🌍 Passport Mode
                    </button>
                    <button 
                        onClick={() => fetchUsers(radius)}
                        style={{ padding: '10px 20px', backgroundColor: '#e11d48', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer', fontWeight: 'bold' }}
                    >
                        🔄 Refresh
                    </button>
                </div>
            </div>

            {/* Filter Card */}
            <div style={{ backgroundColor: 'white', padding: '20px', borderRadius: '12px', boxShadow: '0 4px 6px -1px rgba(0, 0, 0, 0.1)', marginBottom: '30px' }}>
                <label style={{ display: 'block', fontWeight: 'bold', marginBottom: '10px' }}>
                    Search Radius: {radius} km
                </label>
                <div style={{ display: 'flex', gap: '15px', alignItems: 'center' }}>
                    <input 
                        type="range" 
                        min="5" 
                        max="100" 
                        value={radius} 
                        onChange={handleRadiusChange}
                        onMouseUp={handleRadiusSubmit} // Trigger API update when user releases slider
                        style={{ flex: 1 }}
                    />
                </div>
            </div>

            {/* Error / Loading States */}
            {loading && <div style={{ textAlign: 'center', padding: '50px', fontSize: '1.2rem', color: '#6b7280' }}>Locating users near you...</div>}
            {error && <div style={{ backgroundColor: '#fee2e2', color: '#ef4444', padding: '15px', borderRadius: '8px', marginBottom: '20px' }}>{error}</div>}

            {/* User Grid */}
            {!loading && !error && users.length === 0 && (
                <div style={{ textAlign: 'center', padding: '50px', color: '#6b7280' }}>
                    <h2>No users found within {radius} km.</h2>
                    <p>Try expanding your search radius!</p>
                </div>
            )}

            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(250px, 1fr))', gap: '20px' }}>
                {users.map(user => (
                    <div key={user.phone_number} style={{ backgroundColor: 'white', borderRadius: '16px', overflow: 'hidden', boxShadow: '0 4px 6px -1px rgba(0, 0, 0, 0.1)', display: 'flex', flexDirection: 'column' }}>
                        <img 
                            src={fixImageUrl(user.profile_picture_url)} 
                            alt={user.full_name}
                            style={{ width: '100%', height: '250px', objectFit: 'cover' }}
                        />
                        <div style={{ padding: '15px', flex: 1, display: 'flex', flexDirection: 'column' }}>
                            <h3 style={{ margin: '0 0 5px 0', fontSize: '1.2rem' }}>{user.full_name}, {user.age}</h3>
                            <p style={{ margin: '0 0 15px 0', color: '#6b7280', fontSize: '0.9rem' }}>
                                📍 {user.distance_km ? `${user.distance_km} km away` : 'Unknown distance'}
                            </p>

                            <Button 
                                variant="outline-primary" 
                                className="mb-3 w-100 fw-bold"
                                onClick={() => viewProfile ? viewProfile(user) : handleViewProfile(user)}
                            >
                                View Profile 👁️
                            </Button>

                            <div style={{ display: 'flex', justifyContent: 'space-between', marginTop: 'auto', gap: '5px' }}>
                                <button 
                                    onClick={() => handlePass(user.phone_number)}
                                    style={{ flex: 1, padding: '8px', backgroundColor: '#f3f4f6', border: 'none', borderRadius: '8px', color: '#4b5563', fontWeight: 'bold', cursor: 'pointer', fontSize: '0.9rem' }}
                                >
                                    Pass ❌
                                </button>
                                {(() => {
                                    const isAccepted = myMatches.some(m => m.phone === user.phone_number || m.phone_number === user.phone_number);
                                    if (isAccepted) {
                                        return (
                                            <button 
                                                onClick={() => startChat && startChat({...user, name: user.full_name || user.name, phone: user.phone_number || user.phone})}
                                                style={{ flex: 1, padding: '8px', backgroundColor: '#ecfdf5', border: 'none', borderRadius: '8px', color: '#10b981', fontWeight: 'bold', cursor: 'pointer', fontSize: '0.9rem' }}
                                            >
                                                Chat 💬
                                            </button>
                                        );
                                    } else {
                                        return (
                                            <>
                                                <button 
                                                    onClick={() => alert("You must match with this user first before sending a message.")}
                                                    style={{ flex: 1, padding: '8px', backgroundColor: '#eff6ff', border: 'none', borderRadius: '8px', color: '#3b82f6', fontWeight: 'bold', cursor: 'pointer', fontSize: '0.9rem' }}
                                                >
                                                    Message 💬
                                                </button>
                                                <button 
                                                    onClick={() => handleExpressInterest ? handleExpressInterest(user.phone_number || user.phone, user) : handleLike(user.phone_number)}
                                                    style={{ flex: 1, padding: '8px', backgroundColor: '#ecfdf5', border: 'none', borderRadius: '8px', color: '#10b981', fontWeight: 'bold', cursor: 'pointer', fontSize: '0.9rem' }}
                                                >
                                                    Express Interest ❤️
                                                </button>
                                            </>
                                        );
                                    }
                                })()}
                            </div>
                        </div>
                    </div>
                ))}
            </div>

            {/* Profile Modal */}
            <Modal show={showModal} onHide={handleCloseModal} size="lg" centered>
                {selectedUser && (
                    <>
                        <Modal.Header closeButton className="border-0 pb-0">
                            <Modal.Title className="fw-bold fs-3">{selectedUser.full_name}, {selectedUser.age}</Modal.Title>
                        </Modal.Header>
                        <Modal.Body className="pt-2">
                            <div className="text-center mb-4">
                                <img 
                                    src={fixImageUrl(selectedUser.profile_picture_url)} 
                                    alt={selectedUser.full_name}
                                    style={{ width: '100%', maxWidth: '400px', height: '400px', objectFit: 'cover', borderRadius: '16px' }}
                                    className="shadow-sm"
                                />
                            </div>
                            <div className="px-3">
                                <h5 className="fw-bold mb-3">About</h5>
                                <p className="text-muted fs-5 mb-4">
                                    {selectedUser.self_description || "This user hasn't added a description yet."}
                                </p>

                                <h5 className="fw-bold mb-3">Details</h5>
                                <div className="d-flex flex-wrap gap-2 mb-4">
                                    <Badge bg="light" text="dark" className="p-2 fs-6 border">📍 {selectedUser.town}, {selectedUser.county}</Badge>
                                    {selectedUser.gender && <Badge bg="light" text="dark" className="p-2 fs-6 border">👤 {selectedUser.gender}</Badge>}
                                    {selectedUser.education_level && <Badge bg="light" text="dark" className="p-2 fs-6 border">🎓 {selectedUser.education_level}</Badge>}
                                    {selectedUser.profession && <Badge bg="light" text="dark" className="p-2 fs-6 border">💼 {selectedUser.profession}</Badge>}
                                    {selectedUser.marital_status && <Badge bg="light" text="dark" className="p-2 fs-6 border">💍 {selectedUser.marital_status}</Badge>}
                                    {selectedUser.religion && <Badge bg="light" text="dark" className="p-2 fs-6 border">🙏 {selectedUser.religion}</Badge>}
                                </div>
                            </div>
                        </Modal.Body>
                        <Modal.Footer className="border-0">
                            <Button variant="secondary" onClick={handleCloseModal}>
                                Close
                            </Button>
                            <Button variant="success" onClick={() => {
                                if (handleExpressInterest) {
                                    handleExpressInterest(selectedUser.phone_number || selectedUser.phone, selectedUser);
                                } else {
                                    handleLike(selectedUser.phone_number);
                                }
                                handleCloseModal();
                            }}>
                                Express Interest ❤️
                            </Button>
                        </Modal.Footer>
                    </>
                )}
            </Modal>
        </div>
    );
};

export default DiscoverFeed;
